create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, avatar_url text, created_at timestamptz not null default now());
create table if not exists public.song_texts (id uuid primary key default gen_random_uuid(), title text not null, artist text, text_content text not null, source text default 'lrclib', is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.rooms (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, host_id uuid not null references public.profiles(id), status text not null default 'lobby', max_players int not null default 5, created_at timestamptz not null default now(), started_at timestamptz, closed_at timestamptz, expires_at timestamptz not null default now()+interval '30 minutes');
create table if not exists public.room_members (room_id uuid references public.rooms(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, is_ready boolean not null default false, joined_at timestamptz not null default now(), primary key(room_id,user_id));
create table if not exists public.races (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, song_text_id uuid not null references public.song_texts(id), status text not null default 'racing', started_at timestamptz not null, ended_at timestamptz);
create table if not exists public.race_results (id uuid primary key default gen_random_uuid(), race_id uuid not null references public.races(id) on delete cascade, user_id uuid not null references public.profiles(id), wpm numeric not null, accuracy numeric not null, correct_chars int default 0, incorrect_chars int default 0, elapsed_ms int, rank int, is_valid boolean not null default true, created_at timestamptz not null default now(), unique(race_id,user_id));
alter table public.race_results add column if not exists correct_chars int default 0;
alter table public.race_results add column if not exists incorrect_chars int default 0;
alter table public.race_results add column if not exists elapsed_ms int;
alter table public.race_results add column if not exists rank int;
create table if not exists public.chat_messages (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.rooms(id) on delete cascade, user_id uuid not null references public.profiles(id), message text not null check(char_length(message) between 1 and 200), created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.song_texts enable row level security; alter table public.rooms enable row level security; alter table public.room_members enable row level security; alter table public.races enable row level security; alter table public.race_results enable row level security; alter table public.chat_messages enable row level security;
create index if not exists race_results_user_created_idx on public.race_results(user_id,created_at desc);
create unique index if not exists song_texts_title_artist_unique on public.song_texts(lower(title),lower(coalesce(artist,'')));
do $do$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='profiles read authenticated') then create policy "profiles read authenticated" on public.profiles for select to authenticated using(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='profiles insert own') then create policy "profiles insert own" on public.profiles for insert to authenticated with check(auth.uid()=id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='profiles' and policyname='profiles update own') then create policy "profiles update own" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='song_texts' and policyname='songs read active') then create policy "songs read active" on public.song_texts for select to authenticated using(is_active=true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='rooms' and policyname='rooms read authenticated') then create policy "rooms read authenticated" on public.rooms for select to authenticated using(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='rooms' and policyname='rooms create own') then create policy "rooms create own" on public.rooms for insert to authenticated with check(auth.uid()=host_id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='rooms' and policyname='rooms update host') then create policy "rooms update host" on public.rooms for update to authenticated using(auth.uid()=host_id) with check(auth.uid()=host_id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='room_members' and policyname='members read authenticated') then create policy "members read authenticated" on public.room_members for select to authenticated using(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='room_members' and policyname='members join self') then create policy "members join self" on public.room_members for insert to authenticated with check(auth.uid()=user_id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='room_members' and policyname='members update self') then create policy "members update self" on public.room_members for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='races' and policyname='races read authenticated') then create policy "races read authenticated" on public.races for select to authenticated using(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='races' and policyname='races create authenticated') then create policy "races create authenticated" on public.races for insert to authenticated with check(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='race_results' and policyname='results read valid') then create policy "results read valid" on public.race_results for select to authenticated using(is_valid=true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='race_results' and policyname='results insert own') then create policy "results insert own" on public.race_results for insert to authenticated with check(auth.uid()=user_id); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='chat_messages' and policyname='chat read authenticated') then create policy "chat read authenticated" on public.chat_messages for select to authenticated using(true); end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='chat_messages' and policyname='chat insert own') then create policy "chat insert own" on public.chat_messages for insert to authenticated with check(auth.uid()=user_id); end if;
end $do$;

